// A chat widget cannot hold a real credential: everything it knows is in the
// page source. So this secret stops casual drive-by posting and nothing more,
// and the honest mitigation is rate limiting at the proxy plus the fact that
// the agent can only ever read from a public knowledge base. That is written
// down in docs/setup.md rather than implied by the presence of a check.
//
// Compared in constant time anyway. A timing oracle on a weak secret is still a
// timing oracle, and timingSafeEqual costs nothing.
const crypto = require('crypto');

const secret = $env.CHAT_WEBHOOK_SECRET;
if (!secret) throw new Error('CHAT_WEBHOOK_SECRET is not set on this n8n instance');

const MONEY_MARKERS = [
  'refund', 'refunded', 'chargeback', 'charge back', 'money back', 'reimburse',
  'double charged', 'charged twice', 'overcharged', 'dispute', 'credit note',
  'compensation', 'cancel and refund',
];
const LEGAL_MARKERS = ['lawyer', 'solicitor', 'legal action', 'gdpr request', 'ombudsman'];

const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const presented = String(headers['x-chat-secret'] || '');

  const a = Buffer.from(presented.padEnd(secret.length, '\0').slice(0, secret.length), 'utf8');
  const b = Buffer.from(secret, 'utf8');
  if (presented.length !== secret.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('Chat webhook rejected: bad or missing x-chat-secret');
  }

  const body = item.json.body || {};

  // The session id comes from the visitor's localStorage, so it is
  // attacker-controlled. It is only ever a key - never identity, never
  // interpolated into SQL - and the shape is checked so it cannot be used to
  // fill the table with one enormous row.
  const sessionId = String(body.session_id || '').trim();
  if (!/^[A-Za-z0-9_-]{8,128}$/.test(sessionId)) {
    throw new Error('Chat webhook rejected: session_id must be 8-128 characters of [A-Za-z0-9_-]');
  }

  const message = String(body.message || '').trim().slice(0, 4000);
  if (!message) throw new Error('Chat webhook rejected: empty message');

  const haystack = message.toLowerCase();
  const money = MONEY_MARKERS.filter((m) => haystack.includes(m));
  const legal = LEGAL_MARKERS.filter((m) => haystack.includes(m));

  const visitorEmail = String(body.visitor_email || '').trim().toLowerCase() || null;

  out.push({
    json: {
      session_id: sessionId,
      message,
      page_url: String(body.page_url || '').slice(0, 500) || null,
      visitor_email: visitorEmail && /.+@.+\..+/.test(visitorEmail) ? visitorEmail : null,
      // Chat has no upstream message id, so the key is the session plus a hash
      // of what was said. A visitor who sends the same sentence twice in one
      // session is genuinely the same decision; two visitors never collide.
      decision_key:
        'chat:' + sessionId + ':' + crypto.createHash('sha256').update(message).digest('hex').slice(0, 16),
      // The same deterministic sweep workflow 01 runs. Chat does not classify
      // support-vs-not - a visitor who opened the widget is asking for help by
      // definition - but the money rule applies identically on both channels.
      touches_money: money.length > 0 || legal.length > 0,
      keyword_hits: [...money, ...legal].slice(0, 8),
      received_at: new Date().toISOString(),
    },
  });
}

return out;

// Same shape workflow 01 builds. The two channels differ in how they receive a
// question and how they deliver an answer; they do not differ in how the answer
// is produced.
const chat = $('Verify Shared Secret').first().json;

const history = $input
  .all()
  .map((i) => i.json)
  .filter((row) => row && row.content)
  .map((row) => ({ role: row.role, content: row.content }));

return [
  {
    json: {
      ...chat,
      channel: 'chat',
      text: chat.message,
      session_or_thread_id: chat.session_id,
      history,
      history_turns: history.length,
    },
  },
];

const context = $('Build Engine Request').first().json;
const result = $input.first().json ?? {};

return [
  {
    json: {
      ...context,
      grounded: result.grounded === true,
      answer: result.answer ?? null,
      confidence: Number(result.confidence ?? 0),
      used_article_ids: result.used_article_ids ?? [],
      escalate_reason: result.escalate_reason ?? null,
      integration_error: result.integration_error ?? null,
    },
  },
];

const c = $input.first().json;
return [
  {
    json: {
      ...c,
      action: 'auto_replied',
      reply_text: c.answer,
      needs_human: false,
      handover_reason: null,
    },
  },
];

// What the visitor is told when the desk cannot answer. It says so plainly and
// offers a person - it does not improvise, apologise at length, or pretend the
// question was unclear when the truth is that nobody has written the article.
const c = $input.first().json;

let line;
if (c.touches_money) {
  line = 'That one involves money on your account, so I am not going to guess at it. I have passed it to the support team and someone will come back to you here shortly.';
} else if (c.escalate_reason === 'answer_engine_unavailable') {
  line = 'Sorry - I cannot reach our help centre at the moment. I have passed your question to the support team and someone will reply shortly.';
} else {
  line = 'I could not find that in our help centre, and I would rather say so than guess. I have passed your question to the support team and someone will get back to you.';
}

if (c.visitor_email) {
  line += ' We will reply to ' + c.visitor_email + ' as well.';
} else {
  line += ' If you leave an email address I can make sure the reply reaches you.';
}

return [
  {
    json: {
      ...c,
      action: 'handed_to_human',
      reply_text: line,
      needs_human: true,
      handover_reason:
        c.touches_money
          ? 'Touches money or legal matters - never auto-answered, whatever the confidence.'
          : c.escalate_reason === 'no_matching_article'
            ? 'The knowledge base has no article covering this question.'
            : c.escalate_reason === 'not_answerable_from_kb'
              ? 'Articles were found but none of them answer this question.'
              : c.escalate_reason === 'answer_engine_unavailable'
                ? 'The answer engine could not be reached.'
                : 'Confidence ' + c.confidence + ' is below the threshold ' + ($env.SUPPORT_CONFIDENCE_THRESHOLD || '?') + '.',
    },
  },
];

// One named upstream for both branches, so the four nodes below are written
// once rather than twice.
return $input.all();
